"""Changelog and version files from Conventional Commit messages. See task.md."""

from __future__ import annotations

import re
from dataclasses import dataclass
from pathlib import Path


class CommitError(ValueError):
    """Raised when `previous_version` is not a valid `X.Y.Z` version."""


_VERSION_PART = re.compile(r"0|[1-9][0-9]*")
_HEADER = re.compile(r"([a-z]+)(?:\(([^()]*)\))?(!)?:(.*)")
_BREAKING_PREFIXES = ("BREAKING CHANGE:", "BREAKING-CHANGE:")
_SECTION_FOR_TYPE = {"feat": "Features", "fix": "Fixes", "perf": "Performance"}
_SECTIONS = ("Breaking changes", "Features", "Fixes", "Performance")


@dataclass(frozen=True)
class _Commit:
    type: str
    scope: str | None
    description: str
    breaking: bool


def _parse_version(version: str) -> tuple[int, int, int]:
    parts = version.split(".")
    if len(parts) != 3 or not all(_VERSION_PART.fullmatch(p) for p in parts):
        raise CommitError(f"invalid version: {version!r}")
    major, minor, patch = (int(p) for p in parts)
    return major, minor, patch


def _parse_commit(message: str) -> _Commit | None:
    subject, _, body = message.partition("\n\n")
    subject = subject.strip()
    if "\n" in subject:
        return None
    match = _HEADER.fullmatch(subject)
    if match is None:
        return None
    commit_type, scope, bang, rest = match.groups()
    description = rest.strip()
    if not description:
        return None
    scope = (scope or "").strip() or None
    breaking = bang is not None or any(
        line.strip().startswith(_BREAKING_PREFIXES) for line in body.split("\n")
    )
    return _Commit(commit_type, scope, description, breaking)


def _next_version(previous: str, current: tuple[int, int, int], commits: list[_Commit]) -> str:
    major, minor, patch = current
    if any(c.breaking for c in commits):
        return f"{major + 1}.0.0"
    if any(c.type == "feat" for c in commits):
        return f"{major}.{minor + 1}.0"
    if any(c.type in ("fix", "perf") for c in commits):
        return f"{major}.{minor}.{patch + 1}"
    return previous


def _render_changelog(version: str, commits: list[_Commit]) -> str:
    buckets: dict[str, list[tuple[tuple[bool, str, str], str]]] = {s: [] for s in _SECTIONS}
    for c in commits:
        if c.breaking:
            section = "Breaking changes"
        else:
            section = _SECTION_FOR_TYPE.get(c.type)
            if section is None:
                continue
        if c.scope is None:
            key = (True, "", c.description)
            line = f"- {c.description}"
        else:
            key = (False, c.scope, c.description)
            line = f"- **{c.scope}**: {c.description}"
        buckets[section].append((key, line))

    out = [f"## {version}\n"]
    for name in _SECTIONS:
        seen: set[str] = set()
        lines = []
        for _, line in sorted(set(buckets[name])):
            if line not in seen:
                seen.add(line)
                lines.append(line)
        if lines:
            out.append(f"\n### {name}\n\n")
            out.extend(f"{line}\n" for line in lines)
    return "".join(out)


def build(commits: list[str], previous_version: str, out_dir: str) -> None:
    """Write `<out_dir>/CHANGELOG.md` and `<out_dir>/version.txt`."""
    current = _parse_version(previous_version)
    parsed = [c for c in (_parse_commit(m) for m in commits) if c is not None]
    version = _next_version(previous_version, current, parsed)
    changelog = _render_changelog(version, parsed)

    directory = Path(out_dir)
    directory.mkdir(parents=True, exist_ok=True)
    (directory / "CHANGELOG.md").write_bytes(changelog.encode("utf-8"))
    (directory / "version.txt").write_bytes(f"{version}\n".encode("utf-8"))
